    # Run code snippets and populate exact output
    for i, part in enumerate(day_data["parts"]):
        code = part["code"]
        res = subprocess.run([sys.executable, "-c", code], capture_output=True, text=True)
        if res.returncode != 0:
            print(f"Error in Day 54 Part {i+1} code execution:\n{res.stderr}")
